def _hash_locked(manifest_path: Path, key: str) -> list[dict]:
    """Load a hash-locked third-party manifest; a hash mismatch fails closed."""
    if not manifest_path.exists():
        return []
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    entries = []
    for item in manifest.get(key, []):
        path = REPO / item["agent"]
        item = dict(item, present=path.exists())
        if item["present"]:
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            if item.get("sha256") and digest != item["sha256"]:
                raise SystemExit(f"{item['agent']} hash mismatch: expected "
                                 f"{item['sha256']}, found {digest}")
        entries.append(item)
    return entries

