    return a

class _L1Sells:
    """L1's overrides on whichever market layer (`market.py`, lane L2) is used."""

    def sell_orders(self, board, targets=None, fertilizer_need=None) -> list:
        orders = super().sell_orders(board, targets, fertilizer_need)
        if RUSH_LOT and board.day == RUSH_DAY:
            held = int(board.shed.get("MELON", 0) or 0)
            orders = [["SELL", "MELON", min(held, RUSH_LOT)] if o[0] == "SELL" and o[1] == "MELON" else o
                      for o in orders]
        return orders

