class Suite:
    def __init__(self) -> None:
        self.rows: list[tuple[str, bool, float, str]] = []

    def step(self, name: str, argv: list[str], optional: bool = False) -> None:
        started = time.perf_counter()
        try:
            done = subprocess.run(argv, cwd=REPO, capture_output=True, text=True)
            ok = done.returncode == 0
            detail = "" if ok else (done.stderr.strip() or done.stdout.strip()
                                    or f"exit {done.returncode}").splitlines()[-1][:160]
        except FileNotFoundError as error:
            if optional:
                self.rows.append((name, True, 0.0, f"skipped ({error})"))
                return
            ok, detail = False, str(error)[:160]
        self.rows.append((name, ok, time.perf_counter() - started, detail))
        print(f"  [{'ok' if ok else 'FAIL'}] {name}"
              + (f" — {detail}" if detail else ""))

    def assertion(self, name: str, ok: bool, detail: str = "") -> None:
        self.rows.append((name, ok, 0.0, detail))
        print(f"  [{'ok' if ok else 'FAIL'}] {name}" + (f" — {detail}" if detail else ""))

    @property
    def failures(self) -> list[str]:
        return [name for name, ok, _, _ in self.rows if not ok]

def check(name, condition, detail=""):
    print((OK if condition else BAD) + name + (f" — {detail}" if detail else ""))
    if not condition:
        failures.append(name)
    return condition
